<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowRight,MapPin,Check,ChevronUp,ChevronDown,Trash2,LockKeyhole,Map,Footprints,MoreHorizontal,X,Undo2,Navigation} from 'lucide-vue-next'
import {cityApi,emptyCityDraft,isMultiDayDraft} from '../cityApi'
import type {SingleDayDraft,CityProposal,CityStop} from '../cityApi'
import {journey,loadJourney,nameOf,nextCityStop,clone,loadBasket,notify,updateCity,confirmCity,clock,scenicIdFor,plannedActivity,arrivalSummary,usableItinerary,tripDays,focusedDraftDay,focusedRouteDay,focusDay,canUseFocusedDay,tripDateLabel,localDate} from '../journey'
import {assistantLink} from '../assistantHandoff'
import ScenicCover from '../components/ScenicCover.vue'
import ItineraryFlow from '../components/ItineraryFlow.vue'
import {memoryEpoch} from '../voiceDraft'
const moreMenu=ref<HTMLDetailsElement>()
const route=useRoute(),router=useRouter(),busy=ref(false),error=ref(''),editing=ref(false),review=ref(false)
const working=ref<SingleDayDraft>(emptyCityDraft()),day=ref(''),start=ref(''),end=ref(''),previous=ref<SingleDayDraft>()
const proposal=ref<Extract<CityProposal,{status:'needs_confirmation'}>>(),selectedPlace=ref(''),selectedSession=ref(''),completion=ref(false),actualStart=ref(''),actualEnd=ref('')
let disposed=false
const trip=computed(()=>journey.trip),multi=computed(()=>isMultiDayDraft(trip.value?.draft)),viewDraft=computed(()=>multi.value?focusedDraftDay.value||emptyCityDraft():trip.value?.draft as SingleDayDraft|undefined||emptyCityDraft()),next=computed(()=>nextCityStop.value),terminal=computed(()=>trip.value&&['COMPLETED','CANCELLED','ARCHIVED'].includes(trip.value.status))
const places=computed(()=>journey.catalog.filter(x=>x.record.kind==='place'))
const sessions=computed(()=>journey.catalog.filter(x=>x.record.kind==='show_session'&&x.record.business_date===day.value&&x.ready&&!x.record.is_demo))
const completed=computed(()=>viewDraft.value.stops.filter(s=>s.progress==='completed').length||0)
const total=computed(()=>viewDraft.value.stops.length||0)
const dayStatus=(d:{business_date:string;status:string})=>d.status==='closed'||d.business_date<localDate()?'已结束':d.business_date===localDate()?'今天':'未开始'
const officialItinerary=computed(()=>usableItinerary())
const assistantTo=computed(()=>assistantLink(null,terminal.value?undefined:trip.value?.id))
const assistantLabel=computed(()=>total.value&&!terminal.value?'让小汴梁调整行程':'让小汴梁安排行程')
const canRecord=computed(()=>!!next.value&&canUseFocusedDay.value&&!terminal.value&&!(trip.value?.readiness.days?.find(d=>d.day_id===focusedDraftDay.value?.day_id)?.missing_fields||trip.value?.readiness.missing_fields||[]).length)
const hasArrangement=computed(()=>!!trip.value&&(viewDraft.value.stops.length>0||!!viewDraft.value.business_date))
const manualLabel=computed(()=>hasArrangement.value?'手动调整行程':'补充日期和地点')
const payload=():SingleDayDraft=>({...clone(working.value),business_date:day.value||null,starts_at:day.value&&start.value?day.value+'T'+start.value+':00+08:00':null,ends_at:day.value&&end.value?day.value+'T'+end.value+':00+08:00':null})
const timeInput=(iso:string|null)=>iso?clock(iso):''
const changes=computed(()=>{if(!trip.value)return ['新建一份城市安排'];const old=viewDraft.value,n=payload(),result:string[]=[];if(old.business_date!==n.business_date||old.starts_at!==n.starts_at||old.ends_at!==n.ends_at)result.push('调整日期或游玩时段');for(const s of old.stops){const after=n.stops.find(x=>x.stop_id===s.stop_id);if(!after)result.push('移除'+(s.locked?'必去项：':'：')+nameOf(s.place_id));else if(JSON.stringify(after)!==JSON.stringify(s))result.push('调整'+(s.locked?'必去项：':'：')+nameOf(s.place_id))}for(const s of n.stops)if(!old.stops.some(x=>x.stop_id===s.stop_id))result.push('添加：'+nameOf(s.place_id));if(old.stops.map(s=>s.stop_id).join()!==n.stops.map(s=>s.stop_id).join()&&old.stops.length===n.stops.length)result.push('调整后续游览顺序');return result.length?result:['核对并保存当前安排']})
function edit(fresh=false){if(multi.value&&!fresh)return;if(moreMenu.value)moreMenu.value.open=false;error.value='';proposal.value=undefined;working.value=clone(fresh?emptyCityDraft():viewDraft.value);selectedPlace.value='';selectedSession.value='';day.value=working.value.business_date||'';start.value=timeInput(working.value.starts_at);end.value=timeInput(working.value.ends_at);editing.value=true;review.value=false}
function addStop(){if(!selectedPlace.value)return;const p=places.value.find(x=>x.record.fact_id===selectedPlace.value);working.value.stops.push({stop_id:crypto.randomUUID(),place_id:selectedPlace.value,kind:p?.record.place_type==='restaurant'?'dining':'visit',session_id:null,locked:false,duration_seconds:null,progress:'pending',actual_start:null,actual_end:null});selectedPlace.value=''}
function addSession(){const session=sessions.value.find(s=>s.record.fact_id===selectedSession.value);if(!session?.record.stage_place_id)return;if(working.value.stops.some(s=>s.session_id===session.record.fact_id)){error.value='这场演出已经在安排中';return}working.value.stops.push({stop_id:crypto.randomUUID(),place_id:session.record.stage_place_id,kind:'show',session_id:session.record.fact_id,locked:true,duration_seconds:null,progress:'pending',actual_start:null,actual_end:null});selectedSession.value=''}
function move(i:number,d:number){const j=i+d;if(j<0||j>=working.value.stops.length||working.value.stops[j].progress!=='pending')return;const item=working.value.stops.splice(i,1)[0];working.value.stops.splice(j,0,item)}
function reviewEdit(){error.value='';if(day.value&&start.value&&end.value&&end.value<=start.value){error.value='结束时间需要晚于开始时间';return}review.value=true}
async function run(work:()=>Promise<void>){if(busy.value)return;const epoch=memoryEpoch.value;busy.value=true;error.value='';try{await work();if(epoch!==memoryEpoch.value)throw new Error('会话已清除，请重新开始')}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
function applied(){void loadBasket();editing.value=false;review.value=false;proposal.value=undefined;notify('已保存')}
async function save(){if(multi.value&&route.query.new!=='1')return;const epoch=memoryEpoch.value;await run(async()=>{const before=trip.value?clone(viewDraft.value):undefined;if(proposal.value){await confirmCity(proposal.value);previous.value=before;applied();return}if(!trip.value||route.query.new==='1'){const created=await cityApi.create(payload());if(epoch!==memoryEpoch.value)return;journey.trip=created;previous.value=undefined}else{const result=await updateCity({operation:'save_draft',draft:payload()});if(result.proposal?.status==='needs_confirmation'){proposal.value=result.proposal;return}previous.value=before}applied();await router.replace('/city-trip/'+journey.trip!.id)})}
async function action(work:Parameters<typeof updateCity>[0]){await run(async()=>{const result=await updateCity(work);if(result.proposal?.status==='needs_confirmation')proposal.value=result.proposal;else notify('游玩进度已更新')})}
async function acceptAction(){await run(async()=>{if(proposal.value)await confirmCity(proposal.value);proposal.value=undefined})}
function undo(){if(!previous.value)return;if(moreMenu.value)moreMenu.value.open=false;working.value=clone(previous.value);day.value=working.value.business_date||'';start.value=timeInput(working.value.starts_at);end.value=timeInput(working.value.ends_at);editing.value=true;review.value=true;proposal.value=undefined}
async function load(){const epoch=memoryEpoch.value;await run(async()=>{await loadJourney(true);if(epoch!==memoryEpoch.value)return;if(route.params.id){const value=await cityApi.activate(String(route.params.id));if(epoch!==memoryEpoch.value)return;journey.trip=value;await loadBasket()}if(route.query.new==='1')edit(true)})}
function stopTime(s:CityStop){if(s.actual_start)return clock(s.actual_start);const planned=plannedActivity(s.stop_id);if(planned)return clock(planned.starts_at);const session=journey.catalog.find(x=>x.record.kind==='show_session'&&x.record.fact_id===s.session_id);return session?clock(session.record.starts_at):'待核算'}
function stopScenic(s:CityStop){return scenicIdFor(nameOf(s.place_id))}
async function finishNext(){
 if(!next.value||!actualStart.value||!actualEnd.value){error.value='请填写实际开始与结束时间';return}
 const from=actualStart.value+':00+08:00',to=actualEnd.value+':00+08:00'
 if(Date.parse(to)<Date.parse(from)||Date.parse(to)>Date.now()){error.value='请填写已经发生的有效时间';return}
 if(viewDraft.value.starts_at&&Date.parse(from)<Date.parse(viewDraft.value.starts_at)||viewDraft.value.ends_at&&Date.parse(to)>Date.parse(viewDraft.value.ends_at)){error.value='实际时间需要在本次行程范围内';return}
 const stopId=next.value.stop_id,dayId=multi.value?focusedDraftDay.value?.day_id:undefined
 await run(async()=>{if(trip.value?.status!=='ACTIVE')await updateCity({operation:'transition',status:'ACTIVE'});await updateCity({operation:'mark_completed',day_id:dayId,stop_id:stopId,actual_start:from,actual_end:to});completion.value=false;notify('已记录游玩进度')})
}
let returnFocus:HTMLElement|null=null
const modalOpen=computed(()=>editing.value||!!proposal.value||completion.value)
watch(modalOpen,async open=>{if(open){returnFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.journey-editor button,.journey-editor input')?.focus()}else if(returnFocus?.getClientRects().length)returnFocus.focus();else moreMenu.value?.querySelector('summary')?.focus()})
function trapFocus(event:KeyboardEvent){if(!modalOpen.value)return;const panel=document.querySelector<HTMLElement>('.journey-editor');if(!panel)return;if(event.key==='Escape'&&!busy.value){editing.value=false;completion.value=false;proposal.value=undefined;return}if(event.key!=='Tab')return;const controls=[...panel.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),summary')].filter(e=>e.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(()=>document.addEventListener('keydown',trapFocus));onBeforeUnmount(()=>document.removeEventListener('keydown',trapFocus))
watch(memoryEpoch,()=>{editing.value=false;review.value=false;previous.value=undefined;proposal.value=undefined;error.value='记录已删除，请重新开始'})
watch(()=>[route.params.id,route.query.new],()=>{if(!busy.value)void load()})
onMounted(load);onBeforeUnmount(()=>{disposed=true})
</script>
<template><div class="page journey-page">
 <header class="journey-page-heading"><div><h1>{{trip?'我的开封游记':'我的行程'}}</h1><p v-if="trip">{{tripDateLabel(trip.draft)}} <span v-if="!multi&&viewDraft.starts_at">{{clock(viewDraft.starts_at)}}–{{clock(viewDraft.ends_at)}}</span></p></div><details ref="moreMenu" class="journey-more"><summary aria-label="更多行程操作"><MoreHorizontal :size="23"/></summary><div><button v-if="!terminal&&!multi" type="button" @click="edit(!trip)">{{manualLabel}}</button><RouterLink v-if="trip?.status==='ACTIVE'||trip?.status==='PAUSED'" :to="'/city-trip/manage/'+trip.id">确认当前位置</RouterLink><button v-if="previous&&!terminal" type="button" @click="undo">撤销上次修改</button><button v-if="trip?.status==='ACTIVE'" type="button" :disabled="busy" @click="action({operation:'transition',status:'COMPLETED'})">结束这趟行程</button><RouterLink v-if="hasArrangement||terminal" to="/city-trip?new=1">新建行程</RouterLink></div></details></header>
 <div v-if="error" class="error-state" role="alert">{{error}}<button type="button" @click="load">重试</button></div>
 <p v-if="busy&&!trip" role="status" class="loading-inline">正在读取行程…</p>
 <RouterLink :to="assistantTo" class="journey-assistant-card"><img src="/images/assistant/xiaobianliang-character.png" alt=""><div><span>小汴梁</span><strong>{{assistantLabel}}</strong></div><ArrowRight :size="21"/></RouterLink>
 <nav v-if="tripDays.length>1" class="trip-day-selector" aria-label="行程日期"><button v-for="d in tripDays" :key="d.day_id" type="button" :aria-pressed="focusedDraftDay?.day_id===d.day_id" @click="focusDay(d.day_id)"><strong>{{d.business_date}}</strong><span>{{nameOf(d.origin_place_id)}} → {{nameOf(d.destination_place_id)}}</span><small>{{dayStatus(d)}}</small></button></nav>
 <p v-if="multi&&!canUseFocusedDay" class="trip-evidence-note">正在查看 {{focusedDraftDay?.business_date}} 的安排；此日不执行当前位置或进度修改。</p>
 <p v-if="multi&&journey.route?.stale" class="trip-warning">{{journey.route.notice}}</p>
 <template v-if="trip&&(total||officialItinerary)">
 <section v-if="next&&!terminal" class="journey-next-card"><div class="next-destination"><MapPin :size="21"/><div><small>下一站</small><strong>{{nameOf(next.place_id)}}</strong><span>{{next.kind==='dining'?'用餐':next.kind==='show'?'演出':'游览'}} · {{arrivalSummary(next.stop_id)}}</span></div></div><div class="journey-next-actions"><RouterLink :to="'/guide?mode=city&place='+encodeURIComponent(next.place_id)" class="button primary"><Navigation :size="15"/>去这里</RouterLink><button v-if="canRecord" type="button" class="button secondary" :disabled="busy" @click="completion=true">标记已游玩</button><button v-if="trip.status==='ACTIVE'" type="button" class="text-link" :disabled="busy" @click="action({operation:'skip_stop',day_id:multi?focusedDraftDay?.day_id:undefined,stop_id:next.stop_id})">跳过本站</button></div></section>
 <div class="journey-itinerary-heading"><h2>行程安排</h2><RouterLink :to="'/guide?mode=city'+(next?'&place='+encodeURIComponent(next.place_id):'')" class="text-link"><Map :size="15"/>在地图查看</RouterLink></div>
 <p v-if="usableItinerary()?.evidence_mode==='synthetic'" class="trip-evidence-note">演示路线</p><p v-else-if="usableItinerary()?.evidence_mode==='reference_with_estimates'" class="trip-evidence-note">依据已有来源安排 · 路程采用高德预计耗时，营业与供应以现场为准</p><p v-else-if="trip.route_version&&!usableItinerary()" class="trip-evidence-note">路线待更新</p>
 <p v-if="journey.routeError" role="alert" class="error-state">暂时无法读取路线，<button type="button" @click="load">重试</button></p>
 <ItineraryFlow v-if="officialItinerary" :trip="trip" :itinerary="officialItinerary" :day-id="focusedDraftDay?.day_id" :actionable="canUseFocusedDay"/>
 <ol v-else class="journey-timeline"><li v-for="(s,i) in viewDraft.stops" :key="s.stop_id" :class="[s.progress,{next:next?.stop_id===s.stop_id}]"><div class="timeline-clock">{{stopTime(s)}}</div><span class="timeline-pin"><Check v-if="s.progress==='completed'" :size="12"/></span><article class="timeline-stop"><div class="timeline-stop-main"><div><span class="tiny-caption">{{s.progress==='completed'?'已游玩':s.progress==='skipped'?'已跳过':'待游玩'}}</span><h2><RouterLink :to="stopScenic(s)?'/scenic/'+stopScenic(s):'/place/'+encodeURIComponent(s.place_id)">{{nameOf(s.place_id)}}</RouterLink><LockKeyhole v-if="s.locked" :size="14" aria-label="必去"/></h2><p>{{s.kind==='show'?'演出':s.kind==='dining'?'用餐':'游览'}} · {{s.duration_seconds?Math.round(s.duration_seconds/60)+' 分钟':'时长待定'}}</p></div><div v-if="stopScenic(s)" class="timeline-thumb"><ScenicCover :id="stopScenic(s)!" :name="nameOf(s.place_id)" theme="song"/></div></div><div class="stop-inline-actions"><RouterLink :to="'/guide?mode=city&place='+encodeURIComponent(s.place_id)"><MapPin :size="13"/>查看位置</RouterLink></div><p v-if="i<viewDraft.stops.length-1" class="transfer-note"><Footprints :size="13"/>{{arrivalSummary(viewDraft.stops[i+1].stop_id)}}</p></article></li></ol>
 <p v-if="focusedRouteDay?.overnight" class="trip-overnight">过夜点：{{nameOf(focusedRouteDay.overnight.place_id)}} · 住宿条件{{focusedRouteDay.overnight.stay_evidence==='verified'?'已核验':'待核验'}}；此处衔接次日，不绘制跨夜交通。</p>
 <div v-if="completed||trip.status==='ACTIVE'||trip.status==='PAUSED'||terminal" class="journey-progress-row"><span>已游玩 {{completed}} / {{total}} 站</span><progress :value="completed" :max="total" :aria-label="'行程已完成 '+completed+' 项'"/></div>
 </template>
 <div v-else-if="!busy" class="trip-plan-empty"><MapPin :size="28"/><h2>还没有安排</h2><RouterLink to="/" class="text-link">挑选想去的地方 <ArrowRight :size="15"/></RouterLink></div>
 <Teleport to="body"><div v-if="editing" class="journey-modal-backdrop" @click.self="editing=false"><section class="journey-editor" role="dialog" aria-modal="true" :aria-label="review?'确认行程修改':'编辑城市行程'" @keydown.esc="editing=false"><header><div><span class="tiny-caption">{{review?'核对后再保存':'按你的节奏安排'}}</span><h2>{{review?'这次安排有这些变化':'编辑行程'}}</h2></div><button type="button" aria-label="关闭行程编辑" @click="editing=false"><X :size="21"/></button></header>
 <template v-if="review"><div class="change-comparison"><section><h3>原安排</h3><p>{{viewDraft.stops.map(s=>nameOf(s.place_id)).join(' → ')||'尚无已保存地点'}}</p></section><section><h3>修改后</h3><p>{{working.stops.map(s=>nameOf(s.place_id)).join(' → ')||'地点待匹配'}}</p></section></div><ul class="change-list"><li v-for="text in changes" :key="text">{{text}}</li></ul><span class="manual-draft-label">保存为待安排</span><div v-if="proposal" class="important-change"><strong>重要安排需要再次确认</strong><p v-for="impact in proposal.impacts" :key="impact">{{impact}}</p></div></template>
 <template v-else><div class="journey-form-grid"><label>旅行日期<input v-model="day" type="date" :disabled="viewDraft.stops.some(s=>s.progress!=='pending')"></label><label>开始时间<input v-model="start" type="time" :disabled="viewDraft.stops.some(s=>s.progress!=='pending')"></label><label>结束时间<input v-model="end" type="time"></label></div><details class="journey-extra"><summary>出发与返程地点</summary><label>从哪里出发<select v-model="working.origin_place_id"><option :value="null">稍后补充</option><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}{{p.ready?'':' · 待核验'}}</option></select></label><label>返程终点<select v-model="working.destination_place_id"><option :value="null">稍后补充</option><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}{{p.ready?'':' · 待核验'}}</option></select></label></details>
 <div class="editor-stop-list"><article v-for="(s,i) in working.stops" :key="s.stop_id"><div><strong>{{nameOf(s.place_id)}}</strong><small>{{s.progress==='pending'?'待安排':s.progress==='completed'?'已完成，不修改':'已跳过，不修改'}}</small></div><template v-if="s.progress==='pending'"><div class="editor-stop-tools"><button type="button" :disabled="i===0||working.stops[i-1].progress!=='pending'" :aria-label="'上移：'+nameOf(s.place_id)" @click="move(i,-1)"><ChevronUp :size="17"/></button><button type="button" :disabled="i===working.stops.length-1" :aria-label="'下移：'+nameOf(s.place_id)" @click="move(i,1)"><ChevronDown :size="17"/></button><button type="button" :aria-label="'删除：'+nameOf(s.place_id)" @click="working.stops.splice(i,1)"><Trash2 :size="16"/></button></div><label class="editor-lock"><input v-model="s.locked" type="checkbox">必去，调整时保留</label><label v-if="s.kind!=='show'" class="editor-duration">停留分钟<input type="number" min="1" max="1440" :value="s.duration_seconds?Math.round(s.duration_seconds/60):''" placeholder="待定" @input="s.duration_seconds=Number(($event.target as HTMLInputElement).value)*60||null"></label></template></article></div>
 <div v-if="places.length" class="editor-add"><label>添加景点 / 餐饮 / 休息地点<select v-model="selectedPlace"><option value="">选择已有地点</option><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}{{p.ready?'':' · 待核验'}}</option></select></label><button type="button" class="button secondary" :disabled="!selectedPlace" @click="addStop">添加地点</button></div><div v-if="sessions.length" class="editor-add"><label>添加演出场次<select v-model="selectedSession"><option value="">选择当日已核验场次</option><option v-for="s in sessions" :key="s.record.fact_id" :value="s.record.fact_id">{{nameOf(s.record.program_id)}} {{clock(s.record.starts_at)}}</option></select></label><button class="button secondary" :disabled="!selectedSession" type="button" @click="addSession">添加场次</button></div></template>
 <div v-if="error" class="error-state" role="alert">{{error}}</div><footer><button v-if="review" class="button secondary" type="button" :disabled="busy||!!proposal" @click="review=false">返回编辑</button><button v-if="review" class="button primary" type="button" :disabled="busy" @click="save">{{busy?'正在保存…':proposal?'确认重要修改':'确认并保存安排'}}</button><button v-else class="button primary" type="button" @click="reviewEdit">核对这份安排 <ArrowRight :size="16"/></button></footer></section></div>
 <div v-else-if="proposal" class="journey-modal-backdrop"><section class="journey-editor compact" role="dialog" aria-modal="true" aria-label="确认重要安排"><h2>这会改变重要安排</h2><p v-for="text in proposal.impacts" :key="text">{{text}}</p><button class="button primary" :disabled="busy" @click="acceptAction">确认修改</button><button class="button secondary" :disabled="busy" @click="proposal=undefined">保留原安排</button></section></div>
 <div v-if="completion" class="journey-modal-backdrop"><section class="journey-editor compact" role="dialog" aria-modal="true" aria-label="记录本站完成"><h2>记录本站完成</h2><label>实际开始<input v-model="actualStart" type="datetime-local"></label><label>实际结束<input v-model="actualEnd" type="datetime-local"></label><p v-if="error" class="error-state">{{error}}</p><button class="button primary" :disabled="busy" @click="finishNext">确认完成</button><button class="button secondary" @click="completion=false">取消</button></section></div></Teleport>
</div></template>
